import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"明夷","description":"焦氏易林注 - 明夷","frontmatter":{"title":"明夷","description":"焦氏易林注 - 明夷"},"headers":[],"relativePath":"zh/classics/jiaoyilin/036.md","filePath":"zh/classics/jiaoyilin/036.md"}'),l={name:"zh/classics/jiaoyilin/036.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="明夷" tabindex="-1">明夷 <a class="header-anchor" href="#明夷" aria-label="Permalink to “明夷”">​</a></h1><h3 id="明夷-1" tabindex="-1">明夷 <a class="header-anchor" href="#明夷-1" aria-label="Permalink to “明夷”">​</a></h3><h3 id="明夷之乾" tabindex="-1">明夷之乾 <a class="header-anchor" href="#明夷之乾" aria-label="Permalink to “明夷之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>踐履寒冰，十步九尋。雖有苦痛，不為憂病。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《明夷》象。震為踐履，坎為寒、為冰，坤數十，震數九，故曰十步九尋。《禮王制》註：&quot;六尺為步&quot;，《周禮地官媒氏》註：&quot;八尺曰尋&quot;。坎為苦痛、為憂病，震在外故解也。</p><h3 id="明夷之坤" tabindex="-1">明夷之坤 <a class="header-anchor" href="#明夷之坤" aria-label="Permalink to “明夷之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>太公避紂，七十隱處。卒逢聖文，為王室輔。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍用《明夷》象。震為公，坤老故曰太公。坤為惡，故曰紂。坎伏故曰避紂。坤為文，坎為聖、為室，震為王，故曰王室，言太公遇文王為周室輔也。○逢，元本作遭，依宋本、汲古。</p><h3 id="明夷之屯" tabindex="-1">明夷之屯 <a class="header-anchor" href="#明夷之屯" aria-label="Permalink to “明夷之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>日月之塗，所行必到，無有患悔。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮日坎月，震為塗、為行，坎為患。</p><h3 id="明夷之蒙" tabindex="-1">明夷之蒙 <a class="header-anchor" href="#明夷之蒙" aria-label="Permalink to “明夷之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>諷德誦功，美風盛隆。旦輔成周，光濟沖人。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為功德、為言，正反震，故曰諷誦。震為周、為盛、為旦，艮為光，坎為和，沖，和也。震為人，沖人，成王也；旦，周公也。○美風，宋元本作美周，依汲古。</p><h3 id="明夷之需" tabindex="-1">明夷之需 <a class="header-anchor" href="#明夷之需" aria-label="Permalink to “明夷之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>童子無室，未有配合，空坐獨宿。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>伏艮為童子，坎為室，兌毀故無室。坎為合，二五不相應，故無合。坎為獨、為宿。○子，宋元本作女，依汲古。</p><h3 id="明夷之訟" tabindex="-1">明夷之訟 <a class="header-anchor" href="#明夷之訟" aria-label="Permalink to “明夷之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>穿鼻系株，為虎所拘。王母祝詞，禍不成災，惠然肯來。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>艮為鼻，坎為穿，初至四艮二陽穿其中，故曰穿鼻，此與入於淵入字同義，皆謂二也。巽為系、為木，故曰系株，言既穿其鼻復繫於木上也。乾為虎、為王，巽為母，故曰王母。伏震為祝，坎為禍，離為災，風散故脫。</p><h3 id="明夷之師" tabindex="-1">明夷之師 <a class="header-anchor" href="#明夷之師" aria-label="Permalink to “明夷之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>黃帝神明，八字聖聰。佚受大福，天下平康。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為帝，坤黃故曰黃帝。坎為聖、為聰，坤卦數八，震為子，故曰八子。震為福，坤為天下，坎為平，故天下平康。</p><h3 id="明夷之比" tabindex="-1">明夷之比 <a class="header-anchor" href="#明夷之比" aria-label="Permalink to “明夷之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>深谷為陵，衰者復興。亂傾之國，民得安息。中婦病困，遂入冥室。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為谷、為陵，坤為國、為亂、為民，艮止為安息。火為水妃，火伏，故曰中婦病困。坎為室、為冥，坤為死，入冥室，言死也。卦坎為水，坤又為水，故離火病也。《詩小雅》：&quot;高岸為谷，深谷為陵&quot;。</p><h3 id="明夷之小畜" tabindex="-1">明夷之小畜 <a class="header-anchor" href="#明夷之小畜" aria-label="Permalink to “明夷之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>道遠遼絕，路宿多悔。頑囂相聚，生我畏忌。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>乾為道路、為遼遠，坎為宿，坤為悔，故曰路宿多悔。坤為聚、為惡，故曰頑囂相聚。震為生，坎為畏，皆用伏象。○忌，宋元本作惡，依汲古。</p><h3 id="明夷之履" tabindex="-1">明夷之履 <a class="header-anchor" href="#明夷之履" aria-label="Permalink to “明夷之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>旦樹菽豆，暮成藿羹。心之所樂，志快心歡。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏《謙》。震為旦、為樹、為菽豆，坎為暮，巽為藿，坎為心，震為樂。○羹、歡，依宋元，汲古本作藿葉、作心愜，韻似協，然不可從。</p><h3 id="明夷之泰" tabindex="-1">明夷之泰 <a class="header-anchor" href="#明夷之泰" aria-label="Permalink to “明夷之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>切切之患，凶憂不成。虎不敢嚙，利當我身。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為患、為凶憂，兌為虎、為嚙，坤為我、為身，伏巽為利。○嚙，宋元本作齚，依汲古。</p><h3 id="明夷之否" tabindex="-1">明夷之否 <a class="header-anchor" href="#明夷之否" aria-label="Permalink to “明夷之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>王伯遠宿，長婦在室。異庖待食，所求不得。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>震為王、為伯，坤為宿，震伏不見，故曰遠宿。巽為長婦，互艮為室，故曰長婦在室。艮為庖、為待，伏兌為食。艮為求，言與庖廚離異不能得食也。○待，宋元本作恃，依汲古。</p><h3 id="明夷之同人" tabindex="-1">明夷之同人 <a class="header-anchor" href="#明夷之同人" aria-label="Permalink to “明夷之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>寒燠失時，陽旱為災，雖耗無憂。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾寒離火，故曰寒燠失時。離為陽旱、為災，巽隕落故曰耗，故為憂。坎伏故無憂。</p><h3 id="明夷之大有" tabindex="-1">明夷之大有 <a class="header-anchor" href="#明夷之大有" aria-label="Permalink to “明夷之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>雖窮復通，復危不凶，得其明功。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《明夷》象。震為通、為履，坎在震下，故曰履危。</p><h3 id="明夷之謙" tabindex="-1">明夷之謙 <a class="header-anchor" href="#明夷之謙" aria-label="Permalink to “明夷之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>狼虎所宅，不可以居，為我患憂。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為虎狼、為宅，坎坤皆為憂患，故不可居。</p><h3 id="明夷之豫" tabindex="-1">明夷之豫 <a class="header-anchor" href="#明夷之豫" aria-label="Permalink to “明夷之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>喋囁噱嚾，昧冥相摶。多言少實，語無成事。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震言故曰喋囁。噱，大笑。嚾，喧囂也，卦正反艮，故曰相摶，正覆震相背，故曰多言少實，語無成事。○噱嚾，宋元本作處嚁，汲古作處耀。摶，宋元本、汲古訛傳，均依汲古《中孚》之《升》校。</p><h3 id="明夷之隨" tabindex="-1">明夷之隨 <a class="header-anchor" href="#明夷之隨" aria-label="Permalink to “明夷之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>履冰蹈凌，雖困不窮。播鼓登岩，卒無憂凶。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>明夷坎為冰凌，震為蹈履、為通，故不窮。震為鼓，互艮手故曰播鼓。艮為岩，震為登，言登山擊鼓也。○鼓，宋元本作雀，茲依汲古。</p><h3 id="明夷之蠱" tabindex="-1">明夷之蠱 <a class="header-anchor" href="#明夷之蠱" aria-label="Permalink to “明夷之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>文文墨墨，憂禍相雜。南北失志，東西不得。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震東兌西，震亦為南北象，或指大坎。○首句依宋元本，汲古作文墨且墨，文疑汶之訛，汶汶墨墨，言雜亂不明也。</p><h3 id="明夷之臨" tabindex="-1">明夷之臨 <a class="header-anchor" href="#明夷之臨" aria-label="Permalink to “明夷之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>爭訟不已，更相談訽。張季弱口，被髪北走。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《家人》。○口，宋元本訛日，依汲古。</p><h3 id="明夷之觀" tabindex="-1">明夷之觀 <a class="header-anchor" href="#明夷之觀" aria-label="Permalink to “明夷之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>德積逢時，宜其美才。相明輔聖，拜受福休。長女不嫁，後為大悔。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為積，艮為時、為明，伏乾為聖、為休福，艮為拜，故拜受福休。巽為長女，震為嫁，震伏故不嫁。</p><h3 id="明夷之噬嗑" tabindex="-1">明夷之噬嗑 <a class="header-anchor" href="#明夷之噬嗑" aria-label="Permalink to “明夷之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>江水沱泛，思附君子。仲氏爰歸，不我肯顧，侄娣悔恨。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《遯》之《巽》。</p><h3 id="明夷之賁" tabindex="-1">明夷之賁 <a class="header-anchor" href="#明夷之賁" aria-label="Permalink to “明夷之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>光祀春成，陳寶雞鳴。陽明失道，不能自守，消亡為咎。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《井》。○祀，汲古作禮，寶作室，陽作師，均依宋元本。</p><h3 id="明夷之剝" tabindex="-1">明夷之剝 <a class="header-anchor" href="#明夷之剝" aria-label="Permalink to “明夷之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>驚虎無患，虞為我言，賴得以安。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，坤為患，艮安故無患。虞，虞人，守山澤之官，艮為官、為山，故艮為虞人，反震為言。</p><h3 id="明夷之復" tabindex="-1">明夷之復 <a class="header-anchor" href="#明夷之復" aria-label="Permalink to “明夷之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>偽言妄語，轉相詿誤，不知狼處。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為言，坤虛，故曰偽妄、曰詿誤。艮為狼，艮覆坤迷，故不知。○相，汲古作為，依宋元本。</p><h3 id="明夷之無妄" tabindex="-1">明夷之無妄 <a class="header-anchor" href="#明夷之無妄" aria-label="Permalink to “明夷之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>履隙自敵，凶憂來到，痛不能笑。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>互巽為隙，震為履、為笑，伏坤為凶憂，故不能笑。○隙，宋元本作悖，依汲古。能笑，汲古作死哭，依宋元本。</p><h3 id="明夷之大畜" tabindex="-1">明夷之大畜 <a class="header-anchor" href="#明夷之大畜" aria-label="Permalink to “明夷之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>牽尾不前，逆理失臣，惠朔以奔。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為尾、為牽，艮止故不前。坤為理、為臣，坤伏故失臣。乾為朔，互震為奔，衛惠公名朔，初譖急子於宣公，公令急子使齊，其弟壽知之，先往，盜殺之，急子至，又殺之，及朔即位，為諸公子所惡，故出奔，見《左傳桓十六年》。</p><h3 id="明夷之頤" tabindex="-1">明夷之頤 <a class="header-anchor" href="#明夷之頤" aria-label="Permalink to “明夷之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>三狸捕鼠，遮遏前後。死於環城，不得脫走。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>詳《離》之《遯》。</p><h3 id="明夷之大過" tabindex="-1">明夷之大過 <a class="header-anchor" href="#明夷之大過" aria-label="Permalink to “明夷之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>言笑未畢，憂來暴卒。身加檻纜，囚系縛朿。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>大過為棺槨，故為死卦，兌口故曰言笑。伏坤為憂、為身，艮為檻。《史記陳平傳》：&quot;即反接噲載檻車詣長安&quot;，巽為繩，故曰纜。縲，紲也。卦為大坎，坎為囚，巽為系縛，漢人以大過為死卦，故象如此。○畢，宋元本作卒，依汲古。三四句宋元本汲古皆作&quot;身墨丹索，檻囚裝朿&quot;，茲依汲古《既濟》之《大過》校。</p><h3 id="明夷之坎" tabindex="-1">明夷之坎 <a class="header-anchor" href="#明夷之坎" aria-label="Permalink to “明夷之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>陰積不已，雲作滛雨。傷害平陸，民無室屋。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為積、為雲、為雨，重坎故曰滛雨。艮為平陸、為室屋、為民，坎陷，故傷害而無室廬也。</p><h3 id="明夷之離" tabindex="-1">明夷之離 <a class="header-anchor" href="#明夷之離" aria-label="Permalink to “明夷之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>山林麓藪，非人所處。鳥獸無禮，使我心苦。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏艮為山麓，巽為林。</p><h3 id="明夷之咸" tabindex="-1">明夷之咸 <a class="header-anchor" href="#明夷之咸" aria-label="Permalink to “明夷之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>新作初陵，逾蹈難登。三駒推車，跌頓傷頤。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為陵，震為逾蹈、為登，震伏，故難登，言始皇初即位，即穿治驪山為陵，其高大難登也。震為駒、為車，數三故曰三駒，兌毀折故曰跌頓。兌又為頤。○蹈。汲古作陷。頓作損。均依宋元本。</p><h3 id="明夷之恒" tabindex="-1">明夷之恒 <a class="header-anchor" href="#明夷之恒" aria-label="Permalink to “明夷之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>魂微惙惙，屬纊聽絕。擴然大通，復更生活。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>乾為魂，陷陰中成大過，大過死，故曰魂微惙惙。惙惙，短氣貌。巽為纊，兌為絕，震為通、為生，震在上出大過，故更生也。○屬，宋元本作行，依汲古。</p><h3 id="明夷之遯" tabindex="-1">明夷之遯 <a class="header-anchor" href="#明夷之遯" aria-label="Permalink to “明夷之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>欒子作殃，伯氏誅傷。州犁奔楚，去其邑鄉。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。震木故曰欒子，坤為殃、為誅傷，震為伯，故伯氏誅傷。震為犁，坤為州，震為奔、為楚，坤為邑、為鄉，《左傳成十五年》：&quot;晉三卻殺伯宗及欒弗忌，伯宗子伯州犁奔楚&quot;。○楚，宋元本作荊，依汲古。</p><h3 id="明夷之大壯" tabindex="-1">明夷之大壯 <a class="header-anchor" href="#明夷之大壯" aria-label="Permalink to “明夷之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>驕胡犬形，造惡作凶。無所能成，遠自滅身。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。坤為胡，艮為犬，故曰驕胡犬形。坤為凶惡、為身，兌毀故無成，坤死故滅身。</p><h3 id="明夷之晉" tabindex="-1">明夷之晉 <a class="header-anchor" href="#明夷之晉" aria-label="Permalink to “明夷之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>陳詞達情，使安不傾。增榮益譽，以成功名。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為榮譽、為名。○情，宋元本作城，蓋誠之訛，茲依汲古。</p><h3 id="明夷之明夷" tabindex="-1">明夷之明夷 <a class="header-anchor" href="#明夷之明夷" aria-label="Permalink to “明夷之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>他山之錯，與璆為仇。來攻吾城，傷我肌膚，邦家騷憂。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為玉、為璆，坤為城、為邦家，艮為肌膚，三至五艮覆，故曰傷我肌膚。坎為仇、為憂。《詩小雅鶴鳴》篇：&quot;他山之石，可以為錯&quot;，《傳》&quot;錯，石也&quot;，可以琢玉，故與璆為仇。</p><h3 id="明夷之家人" tabindex="-1">明夷之家人 <a class="header-anchor" href="#明夷之家人" aria-label="Permalink to “明夷之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>三杞無棗，家無積莠。使鳩求婦，頑不我許。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>巽為杞，離卦數三，故曰三杞。巽為不果，故無棗。巽為茅、為莠，坎為積、為室家，莠在火上故曰家無積莠。離為鳩，巽為婦、為反，兌言反故不許。</p><h3 id="明夷之睽" tabindex="-1">明夷之睽 <a class="header-anchor" href="#明夷之睽" aria-label="Permalink to “明夷之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>慎禍重患，顏子為友，乃能安存。牢戶系羊，乃能受福。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>坎為禍患，伏艮為顏，與下兌為友。坎為牢，兌羊在坎下，故曰系羊牢戶，坎陷故曰系。○患，宋元本作病，福作慶，依汲古。</p><h3 id="明夷之蹇" tabindex="-1">明夷之蹇 <a class="header-anchor" href="#明夷之蹇" aria-label="Permalink to “明夷之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>鹿得美草，鳴呼其友。九族和睦，不憂飢乏。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《蹇》。</p><h3 id="明夷之解" tabindex="-1">明夷之解 <a class="header-anchor" href="#明夷之解" aria-label="Permalink to “明夷之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>亡玉失鹿，不知所伏。利以避危，全我生福。甘雨時降，年谷有得。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為玉、為鹿，坎為隱伏故亡失。坎為甘雨，震為年、為谷。○谷，宋元本作歲，依汲古。</p><h3 id="明夷之損" tabindex="-1">明夷之損 <a class="header-anchor" href="#明夷之損" aria-label="Permalink to “明夷之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>逢時積德，身受福慶。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>○積德，宋元本作得當，依汲古。</p><h3 id="明夷之益" tabindex="-1">明夷之益 <a class="header-anchor" href="#明夷之益" aria-label="Permalink to “明夷之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>鵠思其雄，欲隨鳳東。順里羽翼，出次須日。中留北邑，復反其室。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為鵠，坤為鳳，震為東、為隨，故欲隨鳳東。震為羽翼，艮為日，艮止，故曰須日、曰中留。坤為邑、為北，艮為室。○須日中，汲古作日中須，茲依宋元本。</p><h3 id="明夷之夬" tabindex="-1">明夷之夬 <a class="header-anchor" href="#明夷之夬" aria-label="Permalink to “明夷之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>環堵倚鋤，升鬥屬口。貧賤所處，心寒悲苦。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用《明夷》象。坤為堵，震為鋤、為升鬥、為口，坤為貧賤。坎為心、為寒、為悲苦。○升鬥，宋元本作升升，悲作昨，依汲古。堵，汲古作緒，依宋元本。</p><h3 id="明夷之姤" tabindex="-1">明夷之姤 <a class="header-anchor" href="#明夷之姤" aria-label="Permalink to “明夷之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>孤獨特處，莫依為輔，心勞志苦。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>巽為寡，故曰孤獨。伏坤為心志、為勞苦。</p><h3 id="明夷之萃" tabindex="-1">明夷之萃 <a class="header-anchor" href="#明夷之萃" aria-label="Permalink to “明夷之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>稷為堯使，西見王母。拜請百福，賜我喜子，長樂富有。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>此用《明夷》象。互震為稷，又為帝、為堯。坎為西，震為王，坤為母，故曰王母。震為百、為福、為富有，又為喜子，喜子，蠨蛸也。劉向《新論》&quot;野人晝見蟢子者，以為有喜樂之瑞&quot;。</p><h3 id="明夷之升" tabindex="-1">明夷之升 <a class="header-anchor" href="#明夷之升" aria-label="Permalink to “明夷之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>鳴條之災，北奔犬胡。左袵為長，國號匈奴。主君旄頭，立為單於。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《無妄》。災，宋元本作郊，為作尊，依汲古。</p><h3 id="明夷之困" tabindex="-1">明夷之困 <a class="header-anchor" href="#明夷之困" aria-label="Permalink to “明夷之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>絕而復通，雖危不窮。終得其願，姬薑相從。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>兌為絕，坎為通，故絕而復通。坎為危，巽為薑，伏震為姬。○危，宋元本作達，依汲古。</p><h3 id="明夷之井" tabindex="-1">明夷之井 <a class="header-anchor" href="#明夷之井" aria-label="Permalink to “明夷之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>陽並悖狂，拔劍自傷，為身生殃。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>並，依宋本、汲古，元本作氏。生，宋元本作坐，依汲古。翟雲升雲：《內經》：陰不勝其陽，則脈流薄疾並乃狂，註：盛，實也。</p><h3 id="明夷之革" tabindex="-1">明夷之革 <a class="header-anchor" href="#明夷之革" aria-label="Permalink to “明夷之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>方圓不同，剛柔異鄉。掘井得石，勞而無功。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>互乾為圓，伏坤為方。乾剛坤柔故曰異鄉。兌為井，乾為石，互巽亦為石。伏坎為勞，掘井得石，不能再掘，故勞而無功。</p><h3 id="明夷之鼎" tabindex="-1">明夷之鼎 <a class="header-anchor" href="#明夷之鼎" aria-label="Permalink to “明夷之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>乘風駕雨，與鳴鳥俱。動舉千里，見我愛母。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為乘，坤為風，故曰乘風。坎為雨，故曰駕雨。震為鳴，艮為鳥，坤為千里、為母。○駕雨，宋元本作雨會，鳴作飛，均依汲古。</p><h3 id="明夷之震" tabindex="-1">明夷之震 <a class="header-anchor" href="#明夷之震" aria-label="Permalink to “明夷之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>三塗五獄，陽城太室。神明所扶，獨無丘革。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《蒙》。</p><h3 id="明夷之艮" tabindex="-1">明夷之艮 <a class="header-anchor" href="#明夷之艮" aria-label="Permalink to “明夷之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>鴟鴞娶婦，深目身。折要不媚，與伯相背。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為鴟鴞，震為娶，伏兌為艮婦，互大離故曰深目。艮為身，坎隱，故曰身。坎為腰、為折，兌為媚，兌伏，故曰不媚。互震為伯、為反艮，故曰相背。○元本作鴞鴟，從宋本、汲古。背，汲古作悖，依宋元本。</p><h3 id="明夷之漸" tabindex="-1">明夷之漸 <a class="header-anchor" href="#明夷之漸" aria-label="Permalink to “明夷之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>轉行軌軌，行近不遠。旦夕入門，與君笑言。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>伏震為旦，坎為夕，艮為門，巽入。震為君、為笑言。</p><h3 id="明夷之歸妹" tabindex="-1">明夷之歸妹 <a class="header-anchor" href="#明夷之歸妹" aria-label="Permalink to “明夷之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>求利離國，逃去我北。復歸其城，不為吾賊。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>伏艮為求、為國、為城，巽為利，在外故曰離國、曰逃去。坎為北、為賊，巽亦為賊，茲曰不為吾賊。似用伏巽。○離，從汲古，宋元本作難。</p><h3 id="明夷之豐" tabindex="-1">明夷之豐 <a class="header-anchor" href="#明夷之豐" aria-label="Permalink to “明夷之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>日月之塗，所行必到。無凶無咎，安寧不殆。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離日兌月，伏震為大塗、為行，伏艮為安寧。</p><h3 id="明夷之旅" tabindex="-1">明夷之旅 <a class="header-anchor" href="#明夷之旅" aria-label="Permalink to “明夷之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>管仲遇桓，得其願歡。膠目啟牢，振冠無憂。笑喜不莊，空言妄行。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為管，坎為仲，震為桓，桓，木表也，故曰管仲遇桓。震為歡，兌為澤、為膠，上離故曰膠目，坎為牢，互震故曰啟牢。艮為冠、為手，故曰振冠。坎憂震解，故曰不憂。《呂氏春秋》：&quot;魯送管仲於齊，鞹其拳，膠其目&quot;。○啟牢，汲古、丁本作殺糾，局本作膠口，依宋元本。</p><h3 id="明夷之巽" tabindex="-1">明夷之巽 <a class="header-anchor" href="#明夷之巽" aria-label="Permalink to “明夷之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>出入蹈踐，動順天時。俯仰有節，禍災不來。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽入震出，伏艮為天、為時，巽順，離為禍災。</p><h3 id="明夷之兌" tabindex="-1">明夷之兌 <a class="header-anchor" href="#明夷之兌" aria-label="Permalink to “明夷之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>內崩中傷，上亂無常。雖有美粟，我不得食。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>互離為亂，兌毀故曰內崩中傷。兌為常，亂故無常。互巽為粟，兌為食。○中傷，宋元本作傷中，常作恆，依汲古。美，汲古作米，依宋元本。</p><h3 id="明夷之渙" tabindex="-1">明夷之渙 <a class="header-anchor" href="#明夷之渙" aria-label="Permalink to “明夷之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>逐禍除患，道德神仙。遏惡萬里，福常在前，身樂以安。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎為患，震為逐，艮為壽，故曰仙。震為神、為道德、為福、為樂，艮為身。○遏，汲古作過，依宋元本。</p><h3 id="明夷之節" tabindex="-1">明夷之節 <a class="header-anchor" href="#明夷之節" aria-label="Permalink to “明夷之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>牛驚馬走，上下渾擾。鼓音不絕，頃公奔敗。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為牛，震為馬，正反艮震故曰牛驚馬走，上下渾擾。震為鼓、為音、為公，兌毀折故敗。○頃，汲古及各本訛項，依宋元本。齊頃公與卻克戰，敗。見《左傳成十三年》。</p><h3 id="明夷之中孚" tabindex="-1">明夷之中孚 <a class="header-anchor" href="#明夷之中孚" aria-label="Permalink to “明夷之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>西上九阪，往來流連。止須時日，虛與有得。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>兌西，震為阪，數九，故曰西上九阪，正覆艮震，故曰往來流連。艮為時日，艮止故曰須。○阪，宋本、汲古皆作陂，依元本。止，汲古作心虛、作靈，依宋元本。</p><h3 id="明夷之小過" tabindex="-1">明夷之小過 <a class="header-anchor" href="#明夷之小過" aria-label="Permalink to “明夷之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>虎怒捕羊，蝟不能攘。艮虎兌羊，卦是坎形，故曰蝟。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>蝟能伏虎，見《龜策傳》註。</p><h3 id="明夷之既濟" tabindex="-1">明夷之既濟 <a class="header-anchor" href="#明夷之既濟" aria-label="Permalink to “明夷之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>涌泉涓涓，南流不絕。卒為江海，壞敗邑里。家無所處，將師襲戰，獲其醜虜。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>重坎，故泉流不絕，故為江海。離為南。○涌，元本作踴，依宋本、汲古。四五兩句依宋元本增，汲古無。</p><h3 id="明夷之未濟" tabindex="-1">明夷之未濟 <a class="header-anchor" href="#明夷之未濟" aria-label="Permalink to “明夷之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>桃弓葦戟，除殘去惡，敵人執服。此用遇卦明夷象。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>震為桃葦，坎為弓，離為戟。丁雲《左傳昭四年》：&quot;桃弧棘矢以除其災&quot;，又《太平御覽》引《禮稽命徵》曰&quot;桃孤葦矢以除疾殃&quot;。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
